steps:
1. EDIT frontend/src/utils/roleConfig.js — add a new `menuGroups` property to each role alongside the existing `menuItems` (keep menuItems unchanged for backward compatibility with any code that reads them directly). The `menuGroups` structure is an array of group objects: `{ label: string, items: menuItem[] }`. A group with label null is rendered as ungrouped (no section header, no collapse). Define menuGroups as follows:

   STUDENT menuGroups:
   - { label: null, items: [Overview, Profile, Settings] }
   - { label: 'Internships', collapsible: true, items: [Applications, Recommendations] }
   - { label: 'AI & Resume', collapsible: true, items: [ATS Resume, AI Intelligence] }
   - { label: 'Career Development', collapsible: true, items: [Skill Evidence, Skill Gaps, Action Plan, Readiness, Digital Twin, Career Paths] }
   - { label: 'My Progress', collapsible: true, items: [Analytics, My Passport, Company Feedback, Success Stories] }
   - { label: 'Learning', collapsible: true, items: [{ path: '/dashboard/learning-resources', label: 'Learning Resources', icon: BookOpen }] }
   - { label: null, items: [{ path: '/dashboard/support', label: 'Contact Support', icon: LifeBuoy, supportMenu: true }] }

   ADMIN/SUPER_ADMIN menuGroups (same for both admin and super_admin keys):
   - { label: null, items: [Overview, Profile] }
   - { label: 'User & Internship Management', collapsible: true, items: [Users, Internships] }
   - { label: 'Applications', collapsible: true, items: [Applications] }
   - { label: 'Billing & Subscriptions', collapsible: true, items: [Subscriptions] }
   - { label: 'Content & Learning', collapsible: true, items: [{ path: '/admin/dashboard/learning-resources', label: 'Learning Resources', icon: BookOpen }, Success Stories] }
   - { label: 'Student Success', collapsible: true, items: [Certificates, Career Insights] }
   - { label: 'Analytics', collapsible: true, items: [Analytics] }
   - { label: 'Website & Settings', collapsible: true, items: [Website Control, Settings] }
   - { label: null, items: [{ path: '/admin/dashboard/support-inbox', label: 'Support Inbox', icon: Headphones, supportMenu: true }] }

   PARTNER menuGroups:
   - { label: null, items: [Overview, Profile] }
   - { label: 'Internship Management', collapsible: true, items: [Internships, Post Internship] }
   - { label: 'Applications', collapsible: true, items: [Applications] }
   - { label: 'Completion & Certificates', collapsible: true, items: [Completion, Certificates] }
   - { label: 'Learning', collapsible: true, items: [{ path: '/partner/dashboard/learning-resources', label: 'Learning Resources', icon: BookOpen }] }
   - { label: 'Analytics', collapsible: true, items: [Analytics] }
   - { label: null, items: [{ path: '/partner/dashboard/support-inbox', label: 'Support Inbox', icon: Headphones, supportMenu: true }, Settings] }

   Import BookOpen from 'lucide-react' at the top of roleConfig.js (it is already imported).
